:root {
  /* Primary - IBM Blue (Carbon Gray 100 dark theme — interactive를 blue-50으로 상향) */
  --color-primary-50:  #001141;  /* blue-100 — 가장 어두운 surface 강조 */
  --color-primary-100: #001D6C;  /* blue-90 */
  --color-primary-200: #002D9C;  /* blue-80 */
  --color-primary-300: #0043CE;  /* blue-70 */
  --color-primary-400: #0F62FE;  /* blue-60 */
  --color-primary-500: #4589FF;  /* blue-50 — dark interactive 기본 */
  --color-primary-600: #78A9FF;  /* blue-40 — hover */
  --color-primary-700: #A6C8FF;  /* blue-30 */
  --color-primary-800: #D0E2FF;  /* blue-20 */
  --color-primary-900: #EDF5FF;  /* blue-10 */

  /* Secondary - Cyan (보조 강조, 다크 대비 위해 라이트니스 상향) */
  --color-secondary-500: #33B1FF;

  /* Neutral - Gray (다크용 반전 램프) */
  --color-neutral-0:    #000000;
  --color-neutral-50:   #161616;  /* gray-100 background */
  --color-neutral-100:  #262626;  /* gray-90 — layer-01 */
  --color-neutral-200:  #393939;  /* gray-80 — layer-02 */
  --color-neutral-300:  #525252;  /* gray-70 */
  --color-neutral-500:  #6F6F6F;  /* gray-60 */
  --color-neutral-700:  #A8A8A8;  /* gray-40 */
  --color-neutral-800:  #C6C6C6;  /* gray-30 */
  --color-neutral-900:  #E0E0E0;  /* gray-20 */
  --color-neutral-1000: #F4F4F4;  /* gray-10 */

  /* Semantic (다크 배경에서 가독성 확보) */
  --color-success-bg: #0E1E13;
  --color-success-fg: #42BE65;
  --color-warning-bg: #2A2014;
  --color-warning-fg: #F1C21B;
  --color-error-bg:   #2D1213;
  --color-error-fg:   #FA4D56;
  --color-info-bg:    #15263F;
  --color-info-fg:    #4589FF;

  /* Surface (Carbon은 ui-01 ~ ui-05 layered tokens, Gray 100 theme) */
  --bg-base:     #161616;       /* background — g100 */
  --bg-subtle:   #262626;       /* layer-01 */
  --bg-elevated: #393939;       /* layer-02 */
  --bg-overlay:  rgba(0,0,0,0.65);  /* overlay */

  /* Text */
  --text-primary:    #F4F4F4;   /* text-primary */
  --text-secondary:  #C6C6C6;   /* text-secondary */
  --text-tertiary:   #8D8D8D;   /* text-helper */
  --text-on-primary: #161616;
  --text-disabled:   #525252;

  /* Border */
  --border-default: #525252;    /* border-strong */
  --border-subtle:  #393939;    /* border-subtle */
  --border-strong:  #6F6F6F;
  --border-focus:   #FFFFFF;    /* focus — Carbon 다크 focus는 흰색 ring */
}

