.btn {
  font: 400 14px/1.43 "IBM Plex Sans", "IBM Plex Sans KR", sans-serif;
  letter-spacing: 0.16px;
  border-radius: 0;
  padding: 0 16px;
  height: 48px;
  display: inline-flex; align-items: center; gap: 8px;
  border: 1px solid transparent;
  transition: background 70ms cubic-bezier(0.2, 0, 0.38, 0.9);
}
.btn-primary { background: var(--color-primary-500); color: #161616; }
.btn-primary:hover { background: var(--color-primary-600); }
.btn-primary:active { background: var(--color-primary-700); }
.btn-primary:focus { outline: 2px solid var(--border-focus); outline-offset: -3px; box-shadow: inset 0 0 0 1px #161616; }
.btn-primary:disabled { background: var(--color-neutral-200); color: var(--text-disabled); }

.btn-secondary { background: var(--color-neutral-300); color: #f4f4f4; }
.btn-secondary:hover { background: var(--color-neutral-200); }
.btn-ghost { background: transparent; color: var(--color-primary-500); }
.btn-ghost:hover { background: var(--color-neutral-200); }
.btn-danger { background: var(--color-error-fg); color: #161616; }
.input {
  background: var(--bg-subtle);
  border: 0;
  border-bottom: 1px solid var(--border-default);
  border-radius: 0;
  padding: 0 16px;
  height: 40px;
  font-size: 14px;
}
.input:focus {
  outline: 2px solid var(--border-focus);
  outline-offset: -2px;
  border-bottom-color: transparent;
}
.input[aria-invalid="true"] { outline: 2px solid var(--color-error-fg); outline-offset: -2px; }
.card { background: var(--bg-subtle); padding: 16px; border-radius: 0; }
.card-elevated { background: var(--bg-elevated); box-shadow: var(--shadow-md); }
.card-outlined { background: var(--bg-base); border: 1px solid var(--border-subtle); }
.tag { padding: 2px 8px; border-radius: var(--radius-full); font-size: 12px; font-weight: 400; }
.tag-solid   { background: var(--color-primary-300); color: #161616; }
.tag-subtle  { background: var(--color-primary-100); color: var(--color-primary-700); }
.tag-outline { border: 1px solid var(--border-default); color: var(--text-primary); }
.shell-header {
  height: 48px;
  background: var(--color-neutral-0);  /* Carbon 헤더는 g100 검정 */
  color: #f4f4f4;
  display: flex; align-items: center; padding: 0 16px;
  border-bottom: 1px solid var(--color-neutral-200);
}
.shell-header a { color: #f4f4f4; padding: 0 16px; height: 48px; display: flex; align-items: center; }
.shell-header a:hover { background: var(--color-neutral-200); }
